('2f9e3d70-0000-4000-8000-000000006010', '2f9e3d70-0000-4000-8000-000000000022', 'decision', $str$Future phases require separate quote + written approval + advance$str$, $str$Phase 3 Zoho Inventory/Stripe ₹20,000+; Phase 4 US growth strategy / monthly retainer. Do not start without written approval and advance. Source: CLAUDE.md.$str$, '2026-07-09T12:00:00Z'::timestamptz, 'filed', $str$Parked until current phases complete and end-of-year product volume known.$str$, 'active', null, (select id from public.app_users where is_active = true order by created_at limit 1)),
